    for especial in Especial.objects.using(alias).select_related('linea').all():
        cargos = list(Cargo.objects.using(alias).filter(especial_id=especial.pk).select_related('variante__multiplicador'))
        directo = bool(cargos) and all(c.tipo == 'diferencia_precio' for c in cargos)
        guardar(especial.nombre, especial.valor, 1 if directo else (general.valor if general else None), especial.linea.nombre)
        for cargo in cargos:
            multiplo = (cargo.variante.multiplicador.valor if cargo.variante.multiplicador_id else general.valor if general else None)
            guardar(especial.nombre, cargo.valor, 1 if cargo.tipo == 'diferencia_precio' else multiplo,
                    f'{especial.linea.nombre} · {cargo.variante.nombre}')


